import{_ as p,a0 as l,w as o,s as r,ao as d,I as i,x as t,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"Bash 中使用控制運算符連接命令 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 中使用控制運算符連接命令 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 中使用控制運算符連接命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 中使用控制運算符連接命令 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181121 Coupled commands with control operators in Bash","title":"Bash 中使用控制運算符連接命令","tag":"201812","desc":""},"relativePath":"201812/20181121 Coupled commands with control operators in Bash.md","filePath":"[post].md"}'),c={name:"201812/20181121 Coupled commands with control operators in Bash.md"};function h(u,s,m,g,k,b){const e=l("Link");return o(),r("div",null,[s[18]||(s[18]=d(`<h1 id="bash-中使用控制運算符連接命令" tabindex="-1">Bash 中使用控制運算符連接命令 <a class="header-anchor" href="#bash-中使用控制運算符連接命令" aria-label="Permalink to “Bash 中使用控制運算符連接命令”">​</a></h1><blockquote><p>在命令列中，使用控制運算符為複合命令添加邏輯。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/osdc-lead-yearbook-best-couple.png?itok=a_99oCdE" alt=""></p><p>經常會使用一些簡單的複合指令，比如説在一個命令列中連接幾個命令。這些命令使用分號分隔，表示一個命令結束。為了在一個命令列中創建一系列簡單的 shell 命令，只需要使用分號把每一條命令分隔開，就像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command1 ; command2 ; command3 ; command4 ;</span></span></code></pre></div><p>最後一個分號你可以不用添加，因為當你按下回車鍵時就表示一個命令的結束，但是為了和其它的保持一致，還是建議加上比較好。</p><p>所有的命令執行都沒有什麼問題 —— 只要沒有什麼意外發生。但是當出問題時到底發生了什麼呢？我們可以預測，並且通過 Bash 中內置的 <code>&amp;&amp;</code> 和 <code>||</code> 運算符跟蹤這些錯誤。這兩個控制運算符提供了一些流控制，可以讓我們改變代碼執行隊列的順序。分號和換行符也被認為是 Bash 的控制運算符。</p><p><code>&amp;&amp;</code> 運算符意義簡單來説就是“如果 <code>command1</code> 執行成功，就接着執行 <code>command2</code>。”如果 <code>command1</code> 因為任何原因執行失敗，那麼 <code>command2</code> 將不執行。這個語法看下來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command1 &amp;&amp; command2</span></span></code></pre></div><p>這樣寫是允許的，因為每一個命令都會返回一個值（RC）給 shell 來表示這個命令在執行的過程中是否執行成功或者失敗。通常，返回值是 <code>0</code> 表示成功，而一個正數值表示不同種類的錯誤。有一些系統管理工具僅僅返回一個 <code>1</code> 來表示所有的錯誤，但是也有很多工具使用其它的正數的返回值來表示各種類型錯誤。</p><p>我們可以很容易的使用腳本來檢查 shell 變量 <code>$?</code>，可以通過命令列表中的下一個命令，或者可以直接使用系統管理工具檢查。我們一起來看這些返回值。運行一個簡單的命令然後立即檢查它的返回值，這個返回值始終是屬於最後一個運行的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ ll ; echo &quot;RC = $?&quot;</span></span>
<span class="line"><span>total 284</span></span>
<span class="line"><span>-rw-rw-r--  1 student student   130 Sep 15 16:21 ascii-program.sh</span></span>
<span class="line"><span>drwxrwxr-x  2 student student  4096 Nov 10 11:09 bin</span></span>
<span class="line"><span>&lt;snip&gt;</span></span>
<span class="line"><span>drwxr-xr-x. 2 student student  4096 Aug 18 10:21 Videos</span></span>
<span class="line"><span>RC = 0</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>這個返回值是 <code>0</code>，表示這個命令執行成功了。現在嘗試使用同樣的命令在一些我們沒有權限的目錄上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ ll /root ; echo &quot;RC = $?&quot;</span></span>
<span class="line"><span>ls: cannot open directory &#39;/root&#39;: Permission denied</span></span>
<span class="line"><span>RC = 2</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div>`,14)),i("p",null,[s[1]||(s[1]=t("這個返回值的含義可以在 ",-1)),a(e,{href:"http://man7.org/linux/man-pages/man1/ls.1.html"},{default:n(()=>[...s[0]||(s[0]=[t("ls 命令的 man 頁面",-1)])]),_:1}),s[2]||(s[2]=t(" 中找到。",-1))]),s[19]||(s[19]=d(`<p>現在我們來試試 <code>&amp;&amp;</code> 這個控制運算符，因為它也可能會被用在一個命令列程序中。我們將從一個簡單的示例開始：創建一個新目錄，如果創建成功就在這個目錄中創建一個文件。</p><p>我們需要一個目錄可以創建其它的目錄。首先，在你的家目錄中創建一個臨時的目錄用來做測試。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ cd ; mkdir testdir</span></span></code></pre></div><p>在 <code>~/testdir</code> 中新建一個目錄，這也應該是一個空目錄，因為是你剛剛創建的，然後創建一個新的空文件在這個新目錄中。下面的命令可以做這些事情。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ mkdir ~/testdir/testdir2 &amp;&amp; touch ~/testdir/testdir2/testfile1</span></span>
<span class="line"><span>[student@studentvm1 ~]$ ll ~/testdir/testdir2/</span></span>
<span class="line"><span>total 0</span></span>
<span class="line"><span>-rw-rw-r-- 1 student student 0 Nov 12 14:13 testfile1</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>我們看到一切都運行得很好，因為 <code>testdir</code> 目錄是訪問且可寫的。然後我們改變 <code>testdir</code> 目錄的權限，讓用户 <code>student</code> 不再具有訪問的權限。操作如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ chmod 076 testdir ; ll | grep testdir</span></span>
<span class="line"><span>d---rwxrw-. 3 student student  4096 Nov 12 14:13 testdir</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>在長列表（<code>ll</code>）命令後面使用 <code>grep</code> 命令來列出 <code>testdir</code> 目錄。你可以看到用户 <code>student</code> 不再有 <code>testdir</code> 目錄的訪問權限。現在我們像之前一樣運行同樣的命令，但是在 <code>testdir</code> 目錄中創建的是一個不同的目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ mkdir ~/testdir/testdir3 &amp;&amp; touch ~/testdir/testdir3/testfile1</span></span>
<span class="line"><span>mkdir: cannot create directory ‘/home/student/testdir/testdir3’: Permission denied</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>儘管我們也同樣得到了一個錯誤的消息，但 <code>&amp;&amp;</code> 控制運算符阻止了 <code>touch</code> 命令的運行，因為在創建 <code>testdir3</code> 目錄的時候發生了錯誤。通過這種複合的流控制可以阻止一些錯誤的發生使事情變亂。但是這樣看起來變得稍微複雜了一些。</p><p><code>||</code> 控制運算符允許添加另一個命令，這個命令在初始程序語句返回值大於 0 時執行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 ~]$ mkdir ~/testdir/testdir3 &amp;&amp; touch ~/testdir/testdir3/testfile1 || echo &quot;An error occurred while creating the directory.&quot;</span></span>
<span class="line"><span>mkdir: cannot create directory ‘/home/student/testdir/testdir3’: Permission denied</span></span>
<span class="line"><span>An error occurred while creating the directory.</span></span>
<span class="line"><span>[student@studentvm1 ~]$</span></span></code></pre></div><p>當我們使用 <code>&amp;&amp;</code> 和 <code>||</code> 控制運算符時，使用流控制的複合命令的語法格式通常是下面這樣的形式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>preceding commands ; command1 &amp;&amp; command2 || command3 ; following commands</span></span></code></pre></div><p>使用控制運算符的複合命令可以在其它命令之前或者之後，這些和控制運算符流控制有關係，但是不受控制運算符流控制的影響。如果不考慮複合命令的流控制中發生的任何事情那麼所有的命令都將執行。</p><p>當程序出問題時，這些流控制運算符使得在命令中處理出錯和通知我們變得更有效率。我直接在命令列中使用它們，也在腳本中使用。</p><p>你可以以 root 用户的身份來刪除這個目錄和它裏面的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@studentvm1 ~]# rm -rf /home/student/testdir</span></span></code></pre></div><p>你是怎樣使用 Bash 控制運算符的呢？在評論區中告訴我們。</p><hr>`,20)),i("p",null,[s[4]||(s[4]=t("via: ",-1)),a(e,{href:"https://opensource.com/article/18/11/control-operators-bash-shell"},{default:n(()=>[...s[3]||(s[3]=[t("https://opensource.com/article/18/11/control-operators-bash-shell",-1)])]),_:1})]),i("p",null,[s[9]||(s[9]=t("作者：",-1)),a(e,{href:"https://opensource.com/users/dboth"},{default:n(()=>[...s[5]||(s[5]=[t("David Both",-1)])]),_:1}),s[10]||(s[10]=t(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[6]||(s[6]=[t("lujun9972",-1)])]),_:1}),s[11]||(s[11]=t(" 譯者：",-1)),a(e,{href:"https://github.com/Jamskr"},{default:n(()=>[...s[7]||(s[7]=[t("Jamskr",-1)])]),_:1}),s[12]||(s[12]=t(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[13]||(s[13]=[t("LCTT",-1)])]),_:1}),s[16]||(s[16]=t(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...s[14]||(s[14]=[t("Linux中國",-1)])]),_:1}),s[17]||(s[17]=t(" 榮譽推出",-1))])])}const y=p(c,[["render",h]]);export{v as __pageData,y as default};
